'use strict';const M=Model,U=OmniUI,$=x=>document.getElementById(x);window.OMNI_PREVIEW=!window.omnibloomHost;let s=null,busy=false,mock={version:1,revision:0,schedule:'manual',siteOrigin:'https://example.org',siteEnabled:true,days:[{day:'2026-11-03',blocked:1240}],lists:[{id:'fixture-essential',name:'Essential privacy · preview',version:'fixture1',enabled:true,available:true},{id:'fixture-annoyances',name:'Annoyance filters · preview',version:'fixture1',enabled:false,available:true}]};function draw(){$('stats').textContent=s?M.total(s).toLocaleString()+' trackers blocked · last 7 days':'Counts unavailable';$('schedule').disabled=!s||busy;$('schedule').value=s?.schedule||'manual';for(const id of['update','reset','site-toggle'])$(id).disabled=!s||busy;$('site').textContent=s?.siteOrigin||'Unavailable';$('site-toggle').textContent=s?.siteEnabled?'Pause protection for this site':'Enable protection for this site';$('lists').replaceChildren();for(const x of s?.lists||[]){const c=document.createElement('article');c.className='tile';const h=document.createElement('h2');h.textContent=x.name;const p=document.createElement('p');p.textContent='Version '+x.version;const button=document.createElement('button');button.dataset.listId=x.id;button.textContent=x.enabled?'Disable list':'Enable list';button.disabled=busy||!x.available;button.onclick=()=>change('list',{id:x.id,enabled:!x.enabled});c.append(h,p,button);$('lists').append(c)}}async function load(){try{s=M.validate(await U.request('tracking.get',{},()=>mock));U.notify(window.OMNI_PREVIEW?'Preview counts and lists · no real requests are blocked.':'Protection settings confirmed.')}catch(_){s=null;U.notify('Protection settings unavailable.')}draw()}function visibleEnabled(e){return e&&e.isConnected&&!e.disabled&&!e.closest('[hidden],[inert]')&&e.getClientRects().length}
function foreignModal(){return [...document.querySelectorAll('dialog[open],[role=dialog][aria-modal=true]:not([hidden])')].some(e=>e.getClientRects().length)}
function holdWriteFocus(){const e=document.activeElement;if(foreignModal()||!$('content').contains(e)||!e.matches('button,select'))return null;const identity={id:e.id,listId:e.dataset.listId,index:[...$('lists').querySelectorAll('button')].indexOf(e)};const status=$('status');status.tabIndex=0;U.focus(status);return identity}
function restoreWriteFocus(identity){if(!identity||document.activeElement!==$('status')||foreignModal())return;let target=identity.listId?[...$('lists').querySelectorAll('button')].find(e=>e.dataset.listId===identity.listId):$(identity.id);if(!visibleEnabled(target)){const all=[...$('lists').querySelectorAll('button')];target=all.map((e,i)=>({e,d:Math.abs(i-Math.max(0,identity.index))})).filter(x=>visibleEnabled(x.e)).sort((a,b)=>a.d-b.d)[0]?.e}if(!visibleEnabled(target))target=$('update');if(visibleEnabled(target))U.focus(target)}
async function change(type,value){if(busy||!s)return;const focusOwner=holdWriteFocus();busy=true;draw();try{const params=M.operation(s,type,value),n=M.validate(await U.request('tracking.change',params,()=>{mock={...mock,revision:mock.revision+1};if(type==='schedule')mock.schedule=value;if(type==='site')mock.siteEnabled=value;if(type==='reset')mock.days=[];if(type==='list')mock.lists=mock.lists.map(x=>x.id===value.id?{...x,enabled:value.enabled}:x);return mock}));if(n.revision<=s.revision)throw Error();s=n;U.notify(window.OMNI_PREVIEW?'Preview updated.':type==='update'?'List update check completed.':'Protection settings updated.')}catch(_){U.notify('Change not confirmed; previous settings retained.')}finally{busy=false;draw();restoreWriteFocus(focusOwner)}}$('schedule').onchange=()=>change('schedule',$('schedule').value);$('update').onclick=()=>change('update',null);$('reset').onclick=()=>change('reset',null);$('site-toggle').onclick=()=>change('site',!s.siteEnabled);load();U.focus($('update'));
